from pathlib import Path
from PIL import Image
import cv2,numpy as np,json,hashlib
R=Path(__file__).resolve().parents[4];P=R/'work/first-day-anime-test/faithful';source=Image.open(P/'helix-pair-cutout.png').convert('RGBA');white=Image.open(P/'helix-camera/white.png');canvas=Image.new('RGBA',white.size);canvas.alpha_composite(source,((white.width-source.width)//2,(white.height-source.height)//2));cap=cv2.VideoCapture(str(P/'helix-camera/helix-camera.mp4'));ok,frame=cap.read();a=cv2.cvtColor(np.array(white),cv2.COLOR_RGB2GRAY);b=cv2.cvtColor(frame,cv2.COLOR_BGR2GRAY);s=cv2.SIFT_create();ka,da=s.detectAndCompute(a,None);kb,db=s.detectAndCompute(b,None);pairs=cv2.BFMatcher().knnMatch(da,db,k=2);good=[m for m,n in pairs if m.distance<.68*n.distance];pa=np.float32([ka[m.queryIdx].pt for m in good]);pb=np.float32([kb[m.trainIdx].pt for m in good]);M,mask=cv2.estimateAffinePartial2D(pa,pb,method=cv2.RANSAC,ransacReprojThreshold=3);assert M is not None and mask.sum()>25
arr=cv2.warpAffine(np.array(canvas),M,(frame.shape[1],frame.shape[0]),flags=cv2.INTER_LANCZOS4);Image.fromarray(arr).save(P/'helix-front-registered.png');(P/'helix-front-registration.json').write_text(json.dumps({'method':'SIFT, ratio .68, RANSAC similarity 3px','inliers':int(mask.sum()),'matrix':M.tolist(),'source_sha256':hashlib.sha256((P/'helix-pair-cutout.png').read_bytes()).hexdigest(),'scope':'Registered original-resolution first view; not a new generated pose.'},indent=2));print(mask.sum(),M)
